        rows.append({'id':id,'pergunta':q,'definicao':q,'unidade':unit,'formula':formula,'numerador':num,'denominador':den,'produto':'Todos os itens do universo declarado; sem filtro conjunto de cadeia' if source in ('credito','formal') else 'Não aplicável à identificação de cultura','classificacao':classification,'territorio':grain,'calendario':period,'granularidade':grain,'fonte':s['nome'],'url':s['url'],'tabelaCampos':fields,'referencia':period,'captura':'Capturado na fonte em '+s['capturadoEm'][:10] if s.get('capturadoEm') else 'Ver data original preservada e commit no manifesto; reuso não é nova captura oficial','revisao':'Coleta oficial registrada no manifesto; a fonte pode revisar valores' if s.get('estadoAcesso')=='COLETA_OFICIAL' else 'Snapshot preservado; última revisão do portal não confirmada','cobertura':grain,'exclusoes':limits,'licenca':s['licenca'],'limitesComparacao':limits,'estado':'OBSERVADO' if not id.startswith('ipca') else 'INDICE OBSERVADO / VALOR CONVERTIDO EM CENARIO'})
